与后置++不同，前置++运算符在C++语法中可以连续对变量使用，即可以++(++a)，这也是在重载前置++运算符时需要返回引用的原因。那么观察以下计时器类Timer的定义
#include<iostream>
using namespace std;
class Timer{
private:
int sec;
public:
Timer(){
sec=0;
}
Timer operator++(){//注意返回值不是引用
sec++;
return *this;
}
void show(){
cout<<sec<<endl;
}
};
int main(){
Timer t;
++(++(++t));//连续调用三次前置++
t.show();
return 0;
}
